// Generated by Skyramp

// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const errors: string[] = [];
    page.on('pageerror', (err) => errors.push(err.message));

    await page.goto(`${baseUrl}/`);

    await expect(page.getByRole("link", { name: "Sunglasses Sunglasses $19.99" })).toBeVisible();

    await page.getByRole("button", { name: "Go to slide 5" }).click();

    await expect(page.getByRole("link", { name: "Hairdryer Hairdryer $24.99" })).toBeVisible();
    await expect(page.getByRole("link", { name: "Sunglasses Sunglasses $19.99" })).toHaveCount(0);

    // The dot for the visible slide must expose its selected state to assistive technology.
    // carousel.js signals it with the carousel-dot--active background colour only, so a screen
    // reader announces nine identical buttons. This assertion FAILS until aria-current is set.
    await expect(page.getByRole("button", { name: "Go to slide 5" })).toHaveAttribute("aria-current", "true");

    expect(errors).toHaveLength(0);
});
